	@Test
	void blankAndNestedBlankTermsNeverLoseTheirOwnerScopeToLexicalIds() {
		var vf = SimpleValueFactory.getInstance();
		assertThat(LmdbFilterOutcomeFeedbackDescriptor.valueIdentity(vf.createBNode("same"))).isNull();
		assertThat(LmdbFilterOutcomeFeedbackDescriptor.valueIdentity(vf.createTripleTerm(vf.createIRI("urn:s"),
				vf.createIRI("urn:p"), vf.createBNode("same")))).isNull();
		var nested = vf.createTripleTerm(vf.createIRI("urn:s"), vf.createIRI("urn:p"),
				vf.createTripleTerm(vf.createIRI("urn:t"), vf.createIRI("urn:q"), vf.createLiteral("value")));
		assertThat(LmdbFilterOutcomeFeedbackDescriptor.valueIdentity(nested)).isNotNull()
				.isEqualTo(LmdbFilterOutcomeFeedbackDescriptor.valueIdentity(nested));
	}

